insert into public.grammar_points (code, language, level, name, explanation_vi) values
  ('zh-ma', 'zh', 1, '吗 — yes/no questions', 'Thêm 吗 vào cuối câu trần thuật để thành câu hỏi có/không.'),
  ('zh-measure', 'zh', 1, 'Number + measure word + noun', 'Giữa số đếm và danh từ phải có lượng từ: 三个朋友, 一本书.'),
  ('zh-le-change', 'zh', 2, '了 at the end: a new situation', '了 cuối câu báo hiệu tình huống mới/thay đổi: 下雪了 (trời đổ tuyết rồi).'),
  ('zh-bi', 'zh', 2, '比 comparisons', 'A 比 B + tính từ. Sau 比 không dùng 很/非常/太; muốn nhấn mạnh dùng 更 hoặc thêm 一点儿/多了 sau tính từ.'),
  ('zh-de', 'zh', 2, '的 / 得 / 地', '的 trước danh từ (我的书), 得 sau động từ chỉ mức độ (跑得快), 地 trước động từ chỉ cách thức (高兴地笑).'),
  ('zh-guo', 'zh', 3, '过 — experience', 'Động từ + 过: đã từng trải qua. Phủ định: 没(有) + động từ + 过, không dùng 了.'),
  ('zh-ba', 'zh', 3, '把 sentences', 'Chủ ngữ + 把 + tân ngữ + động từ + thành phần khác (kết quả, 了…): 我把作业写完了.'),
  ('zh-shi-de', 'zh', 3, '是…的 — stressing how/when/where', 'Nhấn mạnh cách thức, thời gian, nơi chốn của việc đã xảy ra: 他是坐飞机来的.'),
  ('zh-bei', 'zh', 4, '被 passive', 'Tân ngữ (bị tác động) + 被 + người làm + động từ + kết quả: 自行车被弟弟骑走了.'),
  ('zh-suiran', 'zh', 4, '虽然…但是/还是', 'Nhượng bộ: 虽然 A, 但是/还是 B — tuy A nhưng vẫn B.'),
  ('zh-lian-dou', 'zh', 5, '连…都/也', 'Nhấn mạnh trường hợp cực đoan: 连老师都不认识 — đến cả thầy giáo cũng không biết.'),
  ('zh-wulun', 'zh', 5, '无论…都', 'Bất kể điều kiện nào kết quả cũng không đổi: 无论…都/也.'),
  ('zh-yuqi', 'zh', 6, '与其…不如', 'So sánh hai lựa chọn, chọn vế sau: 与其 A, 不如 B — thay vì A, chẳng bằng B.'),
  ('zh-jiran', 'zh', 6, '既然…就', 'Dựa trên sự thật đã có để rút ra kết luận: 既然 A, 就 B — đã A thì B.'),
  ('en-present-simple', 'en', 1, 'Present simple (he/she + -s)', 'Chủ ngữ ngôi thứ ba số ít (he, she, it) → động từ thêm -s/-es: she works.'),
  ('en-there-is', 'en', 1, 'There is / There are', 'There is + danh từ số ít, There are + danh từ số nhiều.'),
  ('en-past-simple', 'en', 2, 'Past simple', 'Việc đã xong trong quá khứ (last weekend, yesterday) → quá khứ đơn; go → went.'),
  ('en-comparatives', 'en', 2, 'Comparatives (-er than)', 'Tính từ ngắn + -er + than: taller than.'),
  ('en-present-perfect', 'en', 3, 'Present perfect with since/for', 'Hành động bắt đầu trong quá khứ và còn tiếp diễn, đi với since/for → have/has + V3.'),
  ('en-first-conditional', 'en', 3, 'First conditional', 'If + hiện tại đơn, will + động từ: khả năng có thật ở tương lai.'),
  ('en-passive', 'en', 4, 'Passive voice', 'be + V3 khi chủ ngữ chịu tác động: The bridge was built.'),
  ('en-relative-clauses', 'en', 4, 'Relative clauses (who/which)', 'who cho người, which cho vật; mệnh đề đứng ngay sau danh từ nó bổ nghĩa.'),
  ('en-third-conditional', 'en', 5, 'Third conditional', 'If + had + V3, would have + V3: giả định trái với quá khứ.'),
  ('en-reported-speech', 'en', 5, 'Reported speech (backshift)', 'Tường thuật sau told/said thường lùi thì: saw → had seen; the day before.'),
  ('en-double-comparative', 'en', 5, 'The more…, the more…', 'Càng… càng…: The + so sánh hơn…, the + so sánh hơn…'),
  ('en-inversion', 'en', 6, 'Inversion after negative adverbials', 'Not only / Hardly / Never… đứng đầu câu → đảo trợ động từ lên trước chủ ngữ.'),
  ('en-inverted-conditional', 'en', 6, 'Inverted conditionals (Had I known…)', 'Bỏ if, đảo had lên đầu: Had I known = If I had known.')
insert into public.assessment_items (id, language, skill, kind, level, prompt, passage, audio, options, answer, explanation_vi, point, rating) values
  ('zh-voc-1a', 'zh', 'vocabulary', 'choice', 1, '「朋友」 nghĩa là gì?', null, null, '["buổi sáng","giáo viên","bạn bè","bệnh viện"]'::jsonb, '2'::jsonb, '朋友 (péngyou) = bạn bè.', null, 800),
  ('zh-voc-1b', 'zh', 'vocabulary', 'choice', 1, '「喝」 nghĩa là gì?', null, null, '["ăn","uống","ngủ","nhìn"]'::jsonb, '1'::jsonb, '喝 (hē) = uống; 吃 = ăn, 看 = nhìn, 睡 = ngủ.', null, 800),
  ('zh-voc-2a', 'zh', 'vocabulary', 'choice', 2, '「准备」 nghĩa là gì?', null, null, '["tham gia","giới thiệu","chuẩn bị","quyết định"]'::jsonb, '2'::jsonb, '准备 (zhǔnbèi) = chuẩn bị.', null, 950),
  ('zh-voc-2b', 'zh', 'vocabulary', 'choice', 2, '「旁边」 nghĩa là gì?', null, null, '["phía trước","đối diện","bên trong","bên cạnh"]'::jsonb, '3'::jsonb, '旁边 (pángbiān) = bên cạnh; 前面 = phía trước, 里面 = bên trong, 对面 = đối diện.', null, 950),
  ('zh-voc-3a', 'zh', 'vocabulary', 'choice', 3, '我对历史很感＿＿。', null, null, '["兴趣","意思","关系","机会"]'::jsonb, '0'::jsonb, '对…感兴趣 = có hứng thú với…', null, 1100),
  ('zh-voc-3b', 'zh', 'vocabulary', 'choice', 3, '「习惯」 nghĩa là gì?', null, null, '["văn hoá","thói quen","lịch sử","kinh nghiệm"]'::jsonb, '1'::jsonb, '习惯 (xíguàn) = thói quen; 经验 = kinh nghiệm, 文化 = văn hoá.', null, 1100),
  ('zh-voc-4a', 'zh', 'vocabulary', 'choice', 4, '这次比赛他没有赢，但他已经尽力了。「尽力」 nghĩa là gì?', null, null, '["cố gắng hết sức","gặp may","bỏ cuộc","luyện tập"]'::jsonb, '0'::jsonb, '尽力 (jìnlì) = dốc hết sức.', null, 1250),
  ('zh-voc-4b', 'zh', 'vocabulary', 'choice', 4, '为了＿＿环境，我们应该少用塑料袋。', null, null, '["保护","保存","保留","保证"]'::jsonb, '0'::jsonb, '保护环境 = bảo vệ môi trường. 保证 = đảm bảo, 保存 = lưu giữ, 保留 = giữ lại.', null, 1250),
  ('zh-voc-5a', 'zh', 'vocabulary', 'choice', 5, '他做事总是很＿＿，从来不出错。', null, null, '["随便","匆忙","马虎","谨慎"]'::jsonb, '3'::jsonb, '谨慎 = cẩn trọng — hợp với 从来不出错 (chưa bao giờ sai). 马虎/随便 = cẩu thả, tuỳ tiện.', null, 1400),
  ('zh-voc-5b', 'zh', 'vocabulary', 'choice', 5, '「犹豫」 nghĩa là gì?', null, null, '["hối hận","lo lắng","do dự","kiên trì"]'::jsonb, '2'::jsonb, '犹豫 (yóuyù) = do dự; 后悔 = hối hận, 担心 = lo lắng, 坚持 = kiên trì.', null, 1400),
  ('zh-voc-6a', 'zh', 'vocabulary', 'choice', 6, '这个问题很复杂，不能一概而论。「一概而论」 nghĩa là gì?', null, null, '["đánh đồng mọi trường hợp","giải quyết ngay","bàn bạc kỹ lưỡng","nói thật ngắn gọn"]'::jsonb, '0'::jsonb, '一概而论 = gộp chung mà bàn, đánh đồng mọi trường hợp như nhau.', null, 1550),
  ('zh-voc-6b', 'zh', 'vocabulary', 'choice', 6, '经过多年努力，他终于在科学界＿＿头角。', null, null, '["出人","脱颖","锋芒","崭露"]'::jsonb, '3'::jsonb, '崭露头角 = bắt đầu tỏ rõ tài năng. (脱颖而出 là thành ngữ khác.)', null, 1550),
  ('zh-gr-1a', 'zh', 'grammar', 'choice', 1, '你是学生＿＿？', null, null, '["过","了","吗","着"]'::jsonb, '2'::jsonb, 'Câu hỏi có/không: thêm 吗 cuối câu.', 'zh-ma', 800),
  ('zh-gr-1b', 'zh', 'grammar', 'order', 1, 'Sắp xếp thành câu: “Tôi có ba người bạn.”', null, null, '["朋友","我","个","三","有"]'::jsonb, '["我有三个朋友"]'::jsonb, 'Số + lượng từ + danh từ: 三个朋友.', 'zh-measure', 800),
  ('zh-gr-2a', 'zh', 'grammar', 'choice', 2, '你看，外面下雪＿＿！', null, null, '["的","过","了","着"]'::jsonb, '2'::jsonb, '了 cuối câu: tình huống mới — trời bắt đầu có tuyết.', 'zh-le-change', 950),
  ('zh-gr-2b', 'zh', 'grammar', 'choice', 2, '今天比昨天＿＿。', null, null, '["很冷","太冷","冷","非常冷"]'::jsonb, '2'::jsonb, 'Sau 比 không dùng 很/非常/太: 今天比昨天冷 (hoặc 冷一点儿 / 更冷).', 'zh-bi', 950),
  ('zh-gr-3a', 'zh', 'grammar', 'order', 3, 'Sắp xếp thành câu: “Tôi làm xong bài tập rồi.”', null, null, '["作业","了","写","把","完","我"]'::jsonb, '["我把作业写完了"]'::jsonb, 'Câu chữ 把: 我 + 把 + 作业 + 写完 + 了.', 'zh-ba', 1100),
  ('zh-gr-3b', 'zh', 'grammar', 'choice', 3, '我从来没去＿＿北京。', null, null, '["着","的","过","了"]'::jsonb, '2'::jsonb, 'Phủ định trải nghiệm: 没 + động từ + 过. Không nói 没去了.', 'zh-guo', 1100),
  ('zh-gr-3c', 'zh', 'grammar', 'order', 3, 'Sắp xếp thành câu: “Anh ấy đến bằng máy bay.”', null, null, '["他","是","来","坐","飞机","的"]'::jsonb, '["他是坐飞机来的"]'::jsonb, '是…的 nhấn mạnh cách thức: 他是坐飞机来的.', 'zh-shi-de', 1100),
  ('zh-gr-4a', 'zh', 'grammar', 'choice', 4, '我的自行车＿＿弟弟骑走了。', null, null, '["被","从","把","对"]'::jsonb, '0'::jsonb, 'Xe đạp bị em trai đạp đi mất → câu bị động với 被.', 'zh-bei', 1250),
  ('zh-gr-4b', 'zh', 'grammar', 'choice', 4, '＿＿下着大雨，他还是去上班了。', null, null, '["虽然","因为","所以","如果"]'::jsonb, '0'::jsonb, '虽然…还是: tuy mưa to nhưng vẫn đi làm.', 'zh-suiran', 1250),
  ('zh-gr-5a', 'zh', 'grammar', 'choice', 5, '这个字太难了，连老师＿＿不认识。', null, null, '["都","又","就","才"]'::jsonb, '0'::jsonb, '连…都: đến cả thầy giáo cũng không biết.', 'zh-lian-dou', 1400),
  ('zh-gr-5b', 'zh', 'grammar', 'choice', 5, '无论天气怎么样，他＿＿坚持跑步。', null, null, '["就","才","再","都"]'::jsonb, '3'::jsonb, '无论…都: bất kể thời tiết thế nào, anh ấy đều kiên trì chạy bộ.', 'zh-wulun', 1400),
  ('zh-gr-6a', 'zh', 'grammar', 'choice', 6, '＿＿在家里等，不如出去找找。', null, null, '["既然","尽管","虽然","与其"]'::jsonb, '3'::jsonb, '与其 A，不如 B: thay vì ngồi nhà chờ, chẳng bằng ra ngoài tìm.', 'zh-yuqi', 1550),
  ('zh-gr-6b', 'zh', 'grammar', 'choice', 6, '＿＿你已经决定了，我就不再说什么了。', null, null, '["既然","虽然","不管","即使"]'::jsonb, '0'::jsonb, '既然…就: bạn đã quyết rồi thì tôi không nói gì nữa.', 'zh-jiran', 1550),
  ('zh-ch-1a', 'zh', 'characters', 'choice', 1, '我＿＿中国人。', null, null, '["事","是","试","市"]'::jsonb, '1'::jsonb, 'Cùng đọc shì: 是 = là; 事 = việc, 市 = thành phố, 试 = thử.', null, 800),
  ('zh-ch-1b', 'zh', 'characters', 'choice', 1, '他＿＿家吃饭。', null, null, '["在","载","再","菜"]'::jsonb, '0'::jsonb, '在 = ở (tại); 再 = lại (lần nữa).', null, 800),
  ('zh-ch-2a', 'zh', 'characters', 'choice', 2, '她跑＿＿很快。', null, null, '["的","德","得","地"]'::jsonb, '2'::jsonb, 'Động từ + 得 + mức độ: 跑得很快.', 'zh-de', 950),
  ('zh-ch-2b', 'zh', 'characters', 'choice', 2, '今天太晚了，我们明天＿＿聊吧。', null, null, '["在","载","才","再"]'::jsonb, '3'::jsonb, '再 = lại, lần nữa (việc chưa xảy ra); 在 = ở / đang.', null, 950),
  ('zh-ch-3a', 'zh', 'characters', 'choice', 3, '他高兴＿＿笑了。', null, null, '["的","得","弟","地"]'::jsonb, '3'::jsonb, 'Trạng ngữ + 地 + động từ: 高兴地笑.', 'zh-de', 1100),
  ('zh-ch-3b', 'zh', 'characters', 'choice', 3, '我坐公共＿＿车去学校。', null, null, '["器","气","期","汽"]'::jsonb, '3'::jsonb, '汽车 (xe hơi) dùng 汽 (bộ thuỷ — hơi nước); 天气/空气 dùng 气.', null, 1100),
  ('zh-ch-4a', 'zh', 'characters', 'choice', 4, '这件事我一定要＿＿真考虑。', null, null, '["仁","任","人","认"]'::jsonb, '3'::jsonb, '认真 (rènzhēn) = nghiêm túc.', null, 1250),
  ('zh-ch-4b', 'zh', 'characters', 'choice', 4, '请把你的意＿＿告诉我。', null, null, '["建","件","间","见"]'::jsonb, '3'::jsonb, '意见 (yìjiàn) = ý kiến; 件 là lượng từ, 建 = xây dựng.', null, 1250),
  ('zh-ch-5a', 'zh', 'characters', 'choice', 5, '他的工作经＿＿很丰富。', null, null, '["验","研","演","严"]'::jsonb, '0'::jsonb, '经验 (jīngyàn) = kinh nghiệm.', null, 1400),
  ('zh-ch-5b', 'zh', 'characters', 'choice', 5, '这个方案还需要进一步完＿＿。', null, null, '["擅","膳","善","扇"]'::jsonb, '2'::jsonb, '完善 (wánshàn) = hoàn thiện; 擅长 = giỏi về.', null, 1400),
  ('zh-ch-6a', 'zh', 'characters', 'choice', 6, '他的成功＿＿不开大家的帮助。', null, null, '["离","里","力","理"]'::jsonb, '0'::jsonb, '离不开 = không thể tách khỏi, không thể thiếu.', null, 1550),
  ('zh-ch-6b', 'zh', 'characters', 'choice', 6, '这篇文章的观点非常＿＿锐。', null, null, '["兼","坚","尖","肩"]'::jsonb, '2'::jsonb, '尖锐 (jiānruì) = sắc bén; 坚 = kiên cố, 肩 = vai, 兼 = kiêm.', null, 1550),
  ('zh-rd-1a', 'zh', 'reading', 'choice', 1, '王明的爸爸做什么工作？', '我叫王明，我是学生。我爸爸是医生。', null, '["医生","学生","老师","服务员"]'::jsonb, '0'::jsonb, '我爸爸是医生 — bố là bác sĩ.', null, 800),
  ('zh-rd-1b', 'zh', 'reading', 'choice', 1, '他们哪天去商店？', '今天星期三。明天我和妈妈去商店买东西。', null, '["星期四","星期二","星期五","星期三"]'::jsonb, '0'::jsonb, 'Hôm nay thứ Tư → ngày mai (明天) là thứ Năm (星期四).', null, 800),
  ('zh-rd-2a', 'zh', 'reading', 'choice', 2, '小李起床以后先做什么？', '小李每天早上六点起床，先跑步，然后吃早饭，八点去公司。', null, '["去公司","跑步","睡觉","吃早饭"]'::jsonb, '1'::jsonb, '先跑步，然后吃早饭 — trước tiên chạy bộ.', null, 950),
  ('zh-rd-2b', 'zh', 'reading', 'choice', 2, '他为什么没买这件衣服？', '这件衣服很漂亮，但是太贵了，所以我没买。', null, '["太大了","太贵了","不漂亮","颜色不好"]'::jsonb, '1'::jsonb, '但是太贵了 — vì quá đắt.', null, 950),
  ('zh-rd-3a', 'zh', 'reading', 'choice', 3, '他什么时候去爬山？', '我本来打算周六去爬山，可是天气预报说周六有大雨，所以我决定周日再去。', null, '["今天","周日","周六","下个月"]'::jsonb, '1'::jsonb, '决定周日再去 — quyết định Chủ nhật mới đi.', null, 1100),
  ('zh-rd-3b', 'zh', 'reading', 'choice', 3, '学生们觉得张老师怎么样？', '张老师上课很有意思，学生们都喜欢他。不过，他留的作业有点儿多。', null, '["课有意思，但作业多","大家都不喜欢他","课没意思，作业也多","课有意思，作业很少"]'::jsonb, '0'::jsonb, '很有意思…不过作业有点儿多.', null, 1100),
  ('zh-rd-4a', 'zh', 'reading', 'choice', 4, '这段话主要想说明什么？', '很多人认为多吃水果一定对身体好。其实，有的水果含糖量很高，吃得太多反而不健康。', null, '["糖对身体很好","应该多吃水果","水果也不能吃太多","水果没有营养"]'::jsonb, '2'::jsonb, '其实…吃得太多反而不健康 — ăn quá nhiều lại không tốt.', null, 1250),
  ('zh-rd-4b', 'zh', 'reading', 'choice', 4, '下面哪个人符合要求？', '这家公司正在招聘一名翻译，要求会说英语和汉语，有两年以上的工作经验。', null, '["会中英文，工作了三年","会中英文，刚毕业","只会英语，工作了五年","会汉语，工作了一年"]'::jsonb, '0'::jsonb, 'Cần cả Anh và Trung + trên 2 năm kinh nghiệm.', null, 1250),
  ('zh-rd-5a', 'zh', 'reading', 'choice', 5, '根据这段话，有些书店是怎么吸引年轻人的？', '随着网购的普及，越来越多的实体书店关门了。但有些书店开始提供咖啡、讲座等服务，把书店变成了一个交流空间，反而吸引了不少年轻人。', null, '["只卖畅销书","降低书的价格","增加服务，变成交流空间","开网店"]'::jsonb, '2'::jsonb, '提供咖啡、讲座等服务，把书店变成了一个交流空间.', null, 1400),
  ('zh-rd-5b', 'zh', 'reading', 'choice', 5, '关于午睡，下面哪项正确？', '研究发现，午睡二十分钟左右能让人下午更有精神，但如果超过一个小时，醒来后反而会觉得更累。', null, '["睡太久反而更累","二十分钟太短了","午睡越久越好","午睡对人没有好处"]'::jsonb, '0'::jsonb, '超过一个小时…反而会觉得更累.', null, 1400),
  ('zh-rd-6a', 'zh', 'reading', 'choice', 6, '现在“内卷”一般指什么？', '所谓“内卷”，原指一种社会文化模式发展到一定阶段后停滞不前，只能在内部变得越来越复杂。如今，人们常用它来形容同行之间的非理性竞争：付出越来越多，回报却并没有相应增加。', null, '["投入不断增加而回报没有相应提高的竞争","社会快速发展","用合作代替竞争","工作越来越轻松"]'::jsonb, '0'::jsonb, '付出越来越多，回报却并没有相应增加.', null, 1550),
  ('zh-rd-6b', 'zh', 'reading', 'choice', 6, '他的作品为什么能长久受欢迎？', '这位作家的小说情节并不复杂，却总能在平淡的日常生活中挖掘出深刻的人性，这也正是他的作品经久不衰的原因。', null, '["描写了很多历史事件","语言特别华丽","从日常生活中写出深刻的人性","情节非常复杂"]'::jsonb, '2'::jsonb, '在平淡的日常生活中挖掘出深刻的人性 — 这正是原因.', null, 1550),
  ('zh-ls-1a', 'zh', 'listening', 'choice', 1, 'Bạn nghe được câu nào?', null, '我想喝水。', '["我想喝茶。","我不想喝水。","我想喝水。","我想睡觉。"]'::jsonb, '2'::jsonb, '我想喝水 — Tôi muốn uống nước.', null, 800),
  ('zh-ls-1b', 'zh', 'listening', 'choice', 1, 'Bây giờ là mấy giờ?', null, '现在三点十分。', '["3:30","10:03","4:10","3:10"]'::jsonb, '3'::jsonb, '三点十分 = 3 giờ 10 phút.', null, 800),
  ('zh-ls-2a', 'zh', 'listening', 'choice', 2, 'Một cân (斤) táo giá bao nhiêu?', null, '这种苹果五块钱一斤。', '["50 tệ","5 tệ","5 hào","15 tệ"]'::jsonb, '1'::jsonb, '五块钱一斤 — 5 tệ một cân.', null, 950),
  ('zh-ls-2b', 'zh', 'listening', 'choice', 2, '他怎么去机场？', null, '明天我坐出租车去机场。', '["坐出租车","坐地铁","开车","坐公共汽车"]'::jsonb, '0'::jsonb, '坐出租车 — đi taxi.', null, 950),
  ('zh-ls-3a', 'zh', 'listening', 'choice', 3, '他今天为什么不去看电影？', null, '我本来想去看电影，但是今天要加班，只好改天了。', '["身体不舒服","没有朋友陪","电影票卖完了","要加班"]'::jsonb, '3'::jsonb, '但是今天要加班 — phải tăng ca.', null, 1100),
  ('zh-ls-3b', 'zh', 'listening', 'choice', 3, '关于这趟火车，可以知道什么？', null, '请大家注意，开往上海的火车晚点二十分钟。', '["提前到了","晚点二十分钟","开往北京","已经开走了"]'::jsonb, '1'::jsonb, '开往上海的火车晚点二十分钟 — tàu đi Thượng Hải trễ 20 phút.', null, 1100),
  ('zh-ls-4a', 'zh', 'listening', 'choice', 4, '说话人的意思是：', null, '与其每天加班到很晚，不如提高工作效率，早点儿回家休息。', '["工作效率已经很高了","休息不重要","应该多加班","应该提高效率，不要总加班"]'::jsonb, '3'::jsonb, '与其…不如: nên nâng cao hiệu suất thay vì tăng ca.', null, 1250),
  ('zh-ls-4b', 'zh', 'listening', 'choice', 4, '说话人觉得这家餐厅怎么样？', null, '这家餐厅的菜虽然有点儿贵，但是味道和服务都没得说。', '["便宜又好吃","味道一般","有点儿贵，但是很好","服务不好"]'::jsonb, '2'::jsonb, '没得说 = không chê vào đâu được.', null, 1250),
  ('zh-ls-5a', 'zh', 'listening', 'choice', 5, '他成功的原因是什么？', null, '他之所以能成功，并不是因为运气好，而是因为他比别人付出了更多的努力。', '["付出了更多努力","运气好","有人帮助","有很多钱"]'::jsonb, '0'::jsonb, '之所以…是因为; 不是…而是 — không phải may mắn mà là nỗ lực.', null, 1400),
  ('zh-ls-5b', 'zh', 'listening', 'choice', 5, '说话人对计划是什么态度？', null, '这个计划听起来不错，可具体怎么落实，我们还得再商量商量。', '["觉得计划很差","马上执行","完全反对","基本认可，但细节要再讨论"]'::jsonb, '3'::jsonb, '听起来不错 (nghe ổn), nhưng cách thực hiện cần bàn thêm.', null, 1400),
  ('zh-ls-6a', 'zh', 'listening', 'choice', 6, '说话人建议怎么做？', null, '面对突如其来的变化，与其抱怨，倒不如静下心来想想，怎样才能把损失降到最低。', '["多抱怨几句","等别人解决","放弃计划","冷静想办法减少损失"]'::jsonb, '3'::jsonb, '与其抱怨，倒不如静下心来想想…把损失降到最低.', null, 1550),
  ('zh-ls-6b', 'zh', 'listening', 'choice', 6, '关于这部电影，下面哪项正确？', null, '这部电影的票房虽然不尽如人意，口碑却出奇地好，不少观众看了两三遍。', '["票房很高，评价很差","票房一般，但评价很好","没有人看","观众只看了一遍"]'::jsonb, '1'::jsonb, '票房不尽如人意 (doanh thu không như ý), 口碑出奇地好 (đánh giá tốt bất ngờ).', null, 1550),
  ('en-voc-1a', 'en', 'vocabulary', 'choice', 1, 'What does “kitchen” mean?', null, null, '["nhà bếp","phòng khách","phòng ngủ","nhà tắm"]'::jsonb, '0'::jsonb, 'kitchen = nhà bếp; bedroom = phòng ngủ, bathroom = nhà tắm, living room = phòng khách.', null, 800),
  ('en-voc-1b', 'en', 'vocabulary', 'choice', 1, 'I drink a cup of ___ every morning.', null, null, '["coffee","rice","bread","chair"]'::jsonb, '0'::jsonb, 'Chỉ đồ uống mới “drink a cup of”: coffee.', null, 800),
  ('en-voc-2a', 'en', 'vocabulary', 'choice', 2, 'What does “borrow” mean?', null, null, '["trả lại","mua","cho mượn","mượn"]'::jsonb, '3'::jsonb, 'borrow = mượn (từ ai); lend = cho mượn; return = trả lại.', null, 950),
  ('en-voc-2b', 'en', 'vocabulary', 'choice', 2, 'The train was ___, so we waited for an hour.', null, null, '["early","empty","late","fast"]'::jsonb, '2'::jsonb, 'Phải chờ một tiếng → tàu đến muộn (late).', null, 950),
  ('en-voc-3a', 'en', 'vocabulary', 'choice', 3, 'She has a lot of ___ in teaching — she has done it for ten years.', null, null, '["expense","experience","expression","experiment"]'::jsonb, '1'::jsonb, 'experience = kinh nghiệm; experiment = thí nghiệm; expense = chi phí.', null, 1100),
  ('en-voc-3b', 'en', 'vocabulary', 'choice', 3, 'What does “afford” mean?', null, null, '["cho phép","cố gắng","đồng ý","có đủ khả năng chi trả"]'::jsonb, '3'::jsonb, 'can''t afford a car = không đủ tiền mua xe.', null, 1100),
  ('en-voc-4a', 'en', 'vocabulary', 'choice', 4, 'The government should ___ more money in public transport.', null, null, '["cost","spend","invest","pay"]'::jsonb, '2'::jsonb, 'invest money in sth = đầu tư vào; spend money on (không dùng in).', null, 1250),
  ('en-voc-4b', 'en', 'vocabulary', 'choice', 4, 'The new policy had a significant ___ on small businesses.', null, null, '["affect","result","impact","cause"]'::jsonb, '2'::jsonb, 'have an impact on = tác động đến. affect là động từ; result/cause không đi với “on” ở đây.', null, 1250),
  ('en-voc-5a', 'en', 'vocabulary', 'choice', 5, 'His explanation was so ___ that nobody understood what he meant.', null, null, '["coherent","ambiguous","explicit","concise"]'::jsonb, '1'::jsonb, 'ambiguous = mơ hồ, nhiều nghĩa → không ai hiểu. explicit/coherent = rõ ràng, mạch lạc.', null, 1400),
  ('en-voc-5b', 'en', 'vocabulary', 'choice', 5, 'What does “mitigate” mean?', null, null, '["trì hoãn","giảm nhẹ, làm dịu bớt","làm trầm trọng thêm","di cư"]'::jsonb, '1'::jsonb, 'mitigate the effects = giảm nhẹ tác động; aggravate = làm trầm trọng thêm.', null, 1400),
  ('en-voc-6a', 'en', 'vocabulary', 'choice', 6, 'The report was criticised for its ___ use of statistics, which made the problem seem worse than it was.', null, null, '["selective","impartial","exhaustive","rigorous"]'::jsonb, '0'::jsonb, 'selective use = chỉ chọn số liệu có lợi → bị chỉ trích. impartial/rigorous là lời khen.', null, 1550),
  ('en-voc-6b', 'en', 'vocabulary', 'choice', 6, 'What does “ubiquitous” mean?', null, null, '["hiếm gặp","mơ hồ","có mặt ở khắp nơi","lỗi thời"]'::jsonb, '2'::jsonb, 'Smartphones are ubiquitous = điện thoại thông minh có ở khắp nơi.', null, 1550),
  ('en-gr-1a', 'en', 'grammar', 'choice', 1, 'She ___ in a bank.', null, null, '["working","work","is work","works"]'::jsonb, '3'::jsonb, 'She + động từ thêm -s: works.', 'en-present-simple', 800),
  ('en-gr-1b', 'en', 'grammar', 'choice', 1, '___ two books on the table.', null, null, '["There is","It is","They is","There are"]'::jsonb, '3'::jsonb, 'Danh từ số nhiều (two books) → There are.', 'en-there-is', 800),
  ('en-gr-2a', 'en', 'grammar', 'choice', 2, 'We ___ to the beach last weekend.', null, null, '["went","were go","have gone","go"]'::jsonb, '0'::jsonb, 'last weekend → quá khứ đơn; go → went. Không dùng hiện tại hoàn thành với mốc thời gian quá khứ.', 'en-past-simple', 950),
  ('en-gr-2b', 'en', 'grammar', 'order', 2, 'Put the words in order: “Anh trai tôi cao hơn tôi.”', null, null, '["taller","My","is","me","brother","than"]'::jsonb, '["My brother is taller than me"]'::jsonb, 'Tính từ ngắn + -er + than: taller than me.', 'en-comparatives', 950),
  ('en-gr-3a', 'en', 'grammar', 'choice', 3, 'I ___ in this city since 2019.', null, null, '["have lived","lived","am living","live"]'::jsonb, '0'::jsonb, 'since 2019 và vẫn đang sống → hiện tại hoàn thành: have lived.', 'en-present-perfect', 1100),
  ('en-gr-3b', 'en', 'grammar', 'choice', 3, 'If it rains tomorrow, we ___ at home.', null, null, '["would have stayed","would stay","will stay","stayed"]'::jsonb, '2'::jsonb, 'Điều kiện loại 1: If + hiện tại, will + V.', 'en-first-conditional', 1100),
  ('en-gr-4a', 'en', 'grammar', 'choice', 4, 'The bridge ___ in 1890.', null, null, '["built","has built","was built","is building"]'::jsonb, '2'::jsonb, 'Cây cầu được xây (bị động, quá khứ): was built.', 'en-passive', 1250),
  ('en-gr-4b', 'en', 'grammar', 'order', 4, 'Put the words in order: “Người phụ nữ sống ở nhà bên cạnh là bác sĩ.”', null, null, '["a","next","woman","who","door","lives","is","doctor","The"]'::jsonb, '["The woman who lives next door is a doctor","The doctor who lives next door is a woman"]'::jsonb, 'Mệnh đề quan hệ who lives next door đứng ngay sau the woman.', 'en-relative-clauses', 1250),
  ('en-gr-5a', 'en', 'grammar', 'choice', 5, 'If I had known about the meeting, I ___ it.', null, null, '["will attend","had attended","would have attended","would attend"]'::jsonb, '2'::jsonb, 'Điều kiện loại 3 (trái với quá khứ): would have + V3.', 'en-third-conditional', 1400),
  ('en-gr-5b', 'en', 'grammar', 'choice', 5, 'She told me that she ___ the film the day before.', null, null, '["had seen","sees","has seen","is seeing"]'::jsonb, '0'::jsonb, 'Tường thuật + “the day before” → lùi thì về quá khứ hoàn thành: had seen.', 'en-reported-speech', 1400),
  ('en-gr-5c', 'en', 'grammar', 'choice', 5, 'The more you practise, ___ you will become.', null, null, '["the more confident","the most confident","most confident","more confident"]'::jsonb, '0'::jsonb, 'Càng… càng…: The more…, the more confident…', 'en-double-comparative', 1400),
  ('en-gr-6a', 'en', 'grammar', 'choice', 6, 'Not only ___ late, but he also forgot the documents.', null, null, '["did he arrive","he arrived","arrived he","he did arrive"]'::jsonb, '0'::jsonb, 'Not only đứng đầu câu → đảo trợ động từ: did he arrive.', 'en-inversion', 1550),
  ('en-gr-6b', 'en', 'grammar', 'choice', 6, 'Had I known about the traffic, I ___ earlier.', null, null, '["would leave","would have left","will leave","had left"]'::jsonb, '1'::jsonb, 'Had I known = If I had known (loại 3) → would have left.', 'en-inverted-conditional', 1550),
  ('en-rd-1a', 'en', 'reading', 'choice', 1, 'How old is Anna?', 'Tom is ten years old. He lives with his parents and his sister, Anna. Anna is six.', null, '["Six","Ten","Sixteen","Four"]'::jsonb, '0'::jsonb, 'Anna is six.', null, 800),
  ('en-rd-1b', 'en', 'reading', 'choice', 1, 'When is the shop closed all day?', 'The shop opens at nine o''clock in the morning and closes at six in the evening. It is closed on Sundays.', null, '["On Mondays","On Sundays","Every morning","On Saturdays"]'::jsonb, '1'::jsonb, 'It is closed on Sundays.', null, 800),
  ('en-rd-2a', 'en', 'reading', 'choice', 2, 'Why can''t Lucy go to the party?', 'Dear Sam, I can''t come to your party on Saturday because I have to visit my grandmother in hospital. I hope you have a great time! — Lucy', null, '["She is ill","She doesn''t like parties","She is visiting her grandmother","She has to work"]'::jsonb, '2'::jsonb, 'because I have to visit my grandmother in hospital.', null, 950),
  ('en-rd-2b', 'en', 'reading', 'choice', 2, 'How much does a student with a card pay?', 'The museum is free for children under 12. Adults pay £8, and students pay £5 with a student card.', null, '["Nothing","£8","£12","£5"]'::jsonb, '3'::jsonb, 'students pay £5 with a student card.', null, 950),
  ('en-rd-3a', 'en', 'reading', 'choice', 3, 'What problem do some home workers have?', 'Many people think working from home saves time because there is no commute. However, some workers say they find it harder to stop working in the evening, so they actually work longer hours.', null, '["They find it hard to start work","They work longer hours","They spend more time travelling","They earn less money"]'::jsonb, '1'::jsonb, 'harder to stop working in the evening, so they actually work longer hours.', null, 1100),
  ('en-rd-3b', 'en', 'reading', 'choice', 3, 'Your book is due on 5 August. What can you do?', 'The library will be closed from 1 to 14 August for repairs. Books due during this time can be returned on 15 August without a late fee.', null, '["Return it on 15 August without paying","Ask the library to collect it","Return it before 1 August only","Pay a late fee"]'::jsonb, '0'::jsonb, 'Books due during this time can be returned on 15 August without a late fee.', null, 1100),
  ('en-rd-4a', 'en', 'reading', 'choice', 4, 'According to the text, the benefit of electric cars…', 'Although electric cars produce no exhaust fumes, their environmental benefit depends largely on how the electricity that powers them is generated. In countries that rely heavily on coal, the advantage is much smaller.', null, '["depends on how the electricity is produced","is the same in every country","is greatest where coal is used","comes mainly from lower prices"]'::jsonb, '0'::jsonb, 'depends largely on how the electricity … is generated.', null, 1250),
  ('en-rd-4b', 'en', 'reading', 'choice', 4, 'What does the study suggest?', 'Researchers asked two groups of students to learn a list of words. One group slept for eight hours afterwards, while the other stayed awake. The next day, the group that had slept remembered significantly more words.', null, '["Sleep helps us remember new information","Staying awake improves memory","Word lists are too hard to learn","Students should study at night"]'::jsonb, '0'::jsonb, 'Nhóm được ngủ nhớ nhiều từ hơn → giấc ngủ giúp ghi nhớ.', null, 1250),
  ('en-rd-5a', 'en', 'reading', 'choice', 5, 'What is the supporters'' main argument?', 'Critics of standardised testing argue that it encourages teachers to “teach to the test”, narrowing the curriculum to the skills that are easily measured. Supporters counter that, without some common measure, it is impossible to identify schools that are failing their pupils.', null, '["Teachers should teach to the test","Tests measure every important skill","A common measure is needed to find schools that are failing","Tests make lessons more interesting"]'::jsonb, '2'::jsonb, 'without some common measure, it is impossible to identify schools that are failing.', null, 1400),
  ('en-rd-5b', 'en', 'reading', 'choice', 5, 'How did the shopkeepers react at first, and why?', 'The town''s decision to pedestrianise its main street was initially met with fierce opposition from shopkeepers, who feared losing customers who arrived by car. Two years on, footfall has risen by a third, and several of the original critics now admit they were mistaken.', null, '["They supported it from the start","They opposed it, expecting fewer customers","They wanted to remove more parking","They were not interested in the plan"]'::jsonb, '1'::jsonb, 'fierce opposition … feared losing customers who arrived by car.', null, 1400),
  ('en-rd-6a', 'en', 'reading', 'choice', 6, 'What is the writer''s main point?', 'The notion that multitasking makes us more productive is, for the most part, an illusion. What we experience as doing several things at once is in fact rapid switching between tasks, and each switch carries a small cognitive cost. Over a day, these costs accumulate, leaving us busier but not more effective.', null, '["Cognitive costs only matter for difficult tasks","People can easily do several things at the same time","Multitasking is the best way to save time","Switching between tasks has hidden costs that reduce effectiveness"]'::jsonb, '3'::jsonb, 'each switch carries a small cognitive cost … busier but not more effective.', null, 1550),
  ('en-rd-6b', 'en', 'reading', 'choice', 6, 'The writer suggests that worries about new media…', 'Far from being a recent phenomenon, concern about the effect of new media on young people''s attention is remarkably persistent: similar anxieties were voiced about novels in the eighteenth century, radio in the 1930s and television in the 1950s.', null, '["were first expressed about television","have always been justified","are completely new","have appeared again and again in history"]'::jsonb, '3'::jsonb, 'Far from being a recent phenomenon … remarkably persistent.', null, 1550),
  ('en-ls-1a', 'en', 'listening', 'choice', 1, 'How many brothers does the speaker have?', null, 'I have two brothers and one sister.', '["None","Two","One","Three"]'::jsonb, '1'::jsonb, 'two brothers and one sister.', null, 800),
  ('en-ls-1b', 'en', 'listening', 'choice', 1, 'Which sentence did you hear?', null, 'Can I have a cup of tea, please?', '["Can I have two cups of tea, please?","Can I have a cup of tea, please?","Can you have a cup of tea, please?","Can I have a cup of coffee, please?"]'::jsonb, '1'::jsonb, 'Nghe kỹ: Can I … a cup of tea.', null, 800),
  ('en-ls-2a', 'en', 'listening', 'choice', 2, 'When does the bus leave?', null, 'The bus leaves at a quarter past eight.', '["8:45","8:15","8:25","7:45"]'::jsonb, '1'::jsonb, 'a quarter past eight = 8 giờ 15; a quarter to nine = 8:45.', null, 950),
  ('en-ls-2b', 'en', 'listening', 'choice', 2, 'What does the speaker want?', null, 'I''d like to book a table for four people on Friday evening.', '["To reserve a table for four","To order four meals to take away","To buy four tickets","To cancel a booking"]'::jsonb, '0'::jsonb, 'book a table = đặt bàn.', null, 950),
  ('en-ls-3a', 'en', 'listening', 'choice', 3, 'How did the speaker travel?', null, 'I was going to take the train, but it was cancelled, so I had to get a taxi instead.', '["By bus","On foot","By train","By taxi"]'::jsonb, '3'::jsonb, 'the train was cancelled, so I had to get a taxi.', null, 1100),
  ('en-ls-3b', 'en', 'listening', 'choice', 3, 'What is the problem?', null, 'Sorry, the blue jacket is sold out in your size, but we still have it in black.', '["The shop has no black jackets","The shop is closed","The blue jacket isn''t available in the customer''s size","The jacket is too expensive"]'::jsonb, '2'::jsonb, 'sold out in your size = hết cỡ của bạn.', null, 1100),
  ('en-ls-4a', 'en', 'listening', 'choice', 4, 'What does the speaker mean?', null, 'Unless we reduce our costs significantly this year, we won''t be able to hire any new staff.', '["They plan to dismiss staff","Hiring new staff depends on cutting costs","Their costs are already low","They will hire new staff anyway"]'::jsonb, '1'::jsonb, 'Unless = if not: nếu không cắt giảm chi phí thì không tuyển được.', null, 1250),
  ('en-ls-4b', 'en', 'listening', 'choice', 4, 'When will the talk start?', null, 'The talk was supposed to start at seven, but the speaker got stuck in traffic, so it''s been pushed back by half an hour.', '["At 8:00","At 7:30","At 6:30","At 7:00"]'::jsonb, '1'::jsonb, 'pushed back by half an hour = lùi lại 30 phút → 7:30.', null, 1250),
  ('en-ls-5a', 'en', 'listening', 'choice', 5, 'What is the speaker''s attitude to the plan?', null, 'I wouldn''t say the plan is flawless, but it''s certainly the most realistic option we''ve been given so far.', '["Completely negative","Not interested","Cautiously positive","Enthusiastic, with no doubts"]'::jsonb, '2'::jsonb, 'Không hoàn hảo nhưng thực tế nhất → tích cực có dè dặt.', null, 1400),
  ('en-ls-5b', 'en', 'listening', 'choice', 5, 'What does the speaker imply?', null, 'Had the warning been issued earlier, far fewer people would have been affected by the flooding.', '["The flood was handled perfectly","No warning was given","The warning came too late","Nobody was affected"]'::jsonb, '2'::jsonb, 'Had the warning been issued earlier = nếu cảnh báo sớm hơn → thực tế cảnh báo đã muộn.', null, 1400),
  ('en-ls-6a', 'en', 'listening', 'choice', 6, 'What is the speaker''s objection?', null, 'It''s not that the proposal lacks merit; it''s just that the timing couldn''t be worse, given the budget cuts we''re facing.', '["There are no budget problems","The timing, not the idea itself","The proposal is too cheap","The idea has no value"]'::jsonb, '1'::jsonb, 'It''s not that … lacks merit; … the timing couldn''t be worse.', null, 1550),
  ('en-ls-6b', 'en', 'listening', 'choice', 6, 'What effect did the new findings have?', null, 'Far from settling the debate, the new findings have only raised further questions about how the original data were collected.', '["They confirmed the original data","They were ignored","They ended the debate","They raised more doubts"]'::jsonb, '3'::jsonb, 'Far from settling the debate = không những không kết thúc tranh luận mà còn…', null, 1550)
insert into public.writing_tasks (id, language, kind, exam, level_min, level_max, topic, title, prompt, prompt_vi, min_length, max_length, words) values
  ('zh-w-self', 'zh', 'paragraph', 'general', 1, 2, 'daily-conversation', '介绍一下你自己', '写一段话介绍你自己：你叫什么名字，做什么工作或学什么，喜欢做什么。', 'Giới thiệu bản thân: tên, công việc/học gì, sở thích.', 30, 80, array['名字', '学生', '喜欢', '朋友', '家']::text[]),
  ('zh-w-weekend', 'zh', 'paragraph', 'general', 2, 3, 'daily-conversation', '我的周末', '你周末一般做什么？写一写你上个周末做了什么，觉得怎么样。', 'Cuối tuần bạn thường làm gì? Kể cuối tuần trước bạn đã làm gì, cảm thấy thế nào.', 50, 120, array['周末', '一般', '有时候', '休息', '打算']::text[]),
  ('zh-w-sport', 'zh', 'paragraph', 'general', 2, 4, 'sports', '我喜欢的运动', '你喜欢什么运动？你多长时间运动一次？运动给你带来了什么？', 'Bạn thích môn thể thao nào, bao lâu tập một lần, nó mang lại gì cho bạn?', 50, 120, array['运动', '比赛', '身体', '坚持', '习惯']::text[]),
  ('zh-w-food', 'zh', 'paragraph', 'general', 2, 4, 'food', '我最喜欢的一道菜', '介绍一道你最喜欢的菜：它是什么味道？怎么做？为什么喜欢它？', 'Giới thiệu món ăn bạn thích nhất: vị thế nào, làm ra sao, vì sao thích.', 60, 140, array['味道', '做法', '材料', '酸', '辣']::text[]),
  ('zh-w-hsk3-sentences', 'zh', 'sentences', 'hsk', 3, 4, null, '用词造句（HSK 3–4）', '用下面每个词写一个完整的句子。句子要有主语和谓语，尽量写得具体一点儿。', 'Đặt một câu hoàn chỉnh với mỗi từ cho sẵn (giống phần viết HSK 3–4).', 40, 150, array['已经', '决定', '关心', '虽然', '一边']::text[]),
  ('zh-w-travel', 'zh', 'paragraph', 'general', 3, 4, 'travel', '一次难忘的旅行', '写一次让你难忘的旅行：去了哪儿？和谁一起？发生了什么？', 'Kể một chuyến đi khó quên: đi đâu, với ai, chuyện gì đã xảy ra.', 80, 160, array['旅游', '风景', '照片', '印象', '难忘']::text[]),
  ('zh-w-movie', 'zh', 'paragraph', 'general', 3, 5, 'movies-tv', '介绍一部电影', '介绍一部你喜欢的电影或电视剧：讲了什么故事？你为什么推荐它？', 'Giới thiệu một bộ phim bạn thích: nội dung gì, vì sao bạn giới thiệu nó.', 80, 160, array['情节', '演员', '感动', '推荐', '结局']::text[]),
  ('zh-w-work', 'zh', 'paragraph', 'general', 4, 5, 'business-career', '我理想的工作', '你理想的工作是什么？你觉得选择工作时什么最重要？', 'Công việc lý tưởng của bạn? Khi chọn việc, điều gì quan trọng nhất?', 80, 180, array['理想', '收入', '压力', '发展', '经验']::text[]),
  ('zh-w-health', 'zh', 'paragraph', 'general', 4, 5, 'health', '保持健康的方法', '谈谈你保持健康的方法，并说明为什么这些方法有用。', 'Nói về cách bạn giữ sức khoẻ và vì sao chúng hiệu quả.', 80, 180, array['锻炼', '饮食', '规律', '睡眠', '坚持']::text[]),
  ('zh-w-tech', 'zh', 'paragraph', 'general', 4, 6, 'technology', '手机改变了我们的生活', '手机给我们的生活带来了哪些变化？有好处也有坏处吗？请举例说明。', 'Điện thoại thay đổi cuộc sống thế nào? Có lợi và có hại không? Cho ví dụ.', 100, 220, array['方便', '依赖', '影响', '交流', '效率']::text[]),
  ('zh-w-hsk5-words', 'zh', 'paragraph', 'hsk', 5, 5, null, '用五个词写短文（HSK 5）', '请结合下面的词语（要全部使用，顺序不分先后），写一篇80字左右的短文。', 'Dùng đủ 5 từ cho sẵn, viết đoạn văn khoảng 80 chữ (phần viết HSK 5).', 80, 120, array['坚持', '目标', '失败', '鼓励', '成功']::text[]),
  ('zh-w-environment', 'zh', 'essay', 'general', 5, 6, 'environment', '城市怎样减少污染', '大城市的空气污染越来越严重。你认为政府和个人应该怎样做？请说明理由。', 'Ô nhiễm không khí ở thành phố lớn ngày càng nặng. Chính phủ và cá nhân nên làm gì? Nêu lý do.', 150, 300, array['环境', '污染', '措施', '公共交通', '意识']::text[]),
  ('zh-w-education', 'zh', 'essay', 'general', 5, 6, 'education', '网课能代替课堂吗？', '有人认为网上学习将来会代替传统课堂。你同意吗？请谈谈你的看法。', 'Có người cho rằng học online sẽ thay thế lớp học truyền thống. Bạn có đồng ý không?', 150, 300, array['网课', '互动', '自律', '灵活', '效果']::text[]),
  ('zh-w-festival', 'zh', 'essay', 'general', 6, 6, 'culture-history', '传统节日的意义', '谈谈传统节日在现代生活中的意义。你觉得传统节日应该怎样传承下去？', 'Ý nghĩa của lễ tết truyền thống trong cuộc sống hiện đại; nên gìn giữ thế nào?', 250, 450, array['传统', '节日', '传承', '团聚', '商业化']::text[]),
  ('en-w-intro', 'en', 'paragraph', 'general', 1, 2, 'daily-conversation', 'About me', 'Introduce yourself: your family, your job or studies, and what you like doing in your free time.', 'Giới thiệu bản thân: gia đình, công việc/học tập, sở thích lúc rảnh.', 50, 100, array['family', 'hobby', 'weekend', 'enjoy', 'usually']::text[]),
  ('en-w-food', 'en', 'paragraph', 'general', 1, 3, 'food', 'My favourite dish', 'Describe your favourite dish. What is in it, how is it made, and why do you like it?', 'Tả món ăn bạn thích nhất: nguyên liệu, cách làm, vì sao thích.', 60, 120, array['ingredient', 'taste', 'recipe', 'spicy', 'traditional']::text[]),
  ('en-w-email-friend', 'en', 'letter', 'general', 2, 3, 'travel', 'Invite a friend', 'Write an email to a friend inviting them to visit your city. Say when to come, where they can stay and what you will do together.', 'Viết email mời bạn đến thăm thành phố của bạn: khi nào, ở đâu, sẽ làm gì.', 80, 140, array['invite', 'recommend', 'visit', 'stay', 'plan']::text[]),
  ('en-w-sport', 'en', 'paragraph', 'general', 2, 4, 'sports', 'Sport and young people', 'Why is sport important for young people? Give two or three reasons with examples.', 'Vì sao thể thao quan trọng với người trẻ? Nêu 2–3 lý do kèm ví dụ.', 100, 180, array['teamwork', 'healthy', 'compete', 'discipline', 'confidence']::text[]),
  ('en-w-film', 'en', 'paragraph', 'general', 2, 4, 'movies-tv', 'A film review', 'Write a short review of a film or series you enjoyed: what it is about, what was good, and who you would recommend it to.', 'Viết review ngắn một bộ phim bạn thích: nội dung, điểm hay, nên giới thiệu cho ai.', 100, 180, array['plot', 'character', 'performance', 'ending', 'recommend']::text[]),
  ('en-w-job', 'en', 'paragraph', 'general', 3, 4, 'business-career', 'My ideal job', 'Describe your ideal job and explain why it would suit you.', 'Mô tả công việc lý tưởng và giải thích vì sao nó hợp với bạn.', 120, 200, array['salary', 'flexible', 'colleague', 'responsibility', 'career']::text[]),
  ('en-w-complaint', 'en', 'letter', 'ielts', 3, 5, 'travel', 'Letter of complaint (IELTS GT Task 1)', 'You recently stayed at a hotel and were not happy with it. Write a letter to the manager. In your letter: describe the problems, explain how they affected your stay, and say what you would like the hotel to do.', 'Thư phàn nàn với quản lý khách sạn: vấn đề gì, ảnh hưởng thế nào, muốn khách sạn làm gì (IELTS General Task 1, ≥ 150 từ).', 150, 220, array['disappointed', 'inconvenience', 'staff', 'refund', 'resolve']::text[]),
  ('en-w-ielts-tech', 'en', 'essay', 'ielts', 4, 6, 'technology', 'Technology and social life (IELTS Task 2)', 'Some people believe that modern technology has made people less social. To what extent do you agree or disagree?', 'Công nghệ khiến con người ít giao tiếp xã hội hơn — bạn đồng ý đến mức nào? (IELTS Task 2, ≥ 250 từ).', 250, 350, array['interaction', 'isolated', 'convenient', 'significantly', 'nevertheless']::text[]),
  ('en-w-ielts-env', 'en', 'essay', 'ielts', 4, 6, 'environment', 'Free public transport (IELTS Task 2)', 'Some people think governments should make public transport free to reduce pollution. Others think this is a waste of public money. Discuss both views and give your own opinion.', 'Có nên miễn phí giao thông công cộng để giảm ô nhiễm? Bàn cả hai quan điểm và nêu ý kiến của bạn.', 250, 350, array['emissions', 'congestion', 'fund', 'incentive', 'sustainable']::text[]),
  ('en-w-ielts-edu', 'en', 'essay', 'ielts', 4, 6, 'education', 'Online learning (IELTS Task 2)', 'Online learning will soon replace traditional classrooms. Do you agree or disagree?', 'Học trực tuyến sẽ sớm thay thế lớp học truyền thống — đồng ý hay không?', 250, 350, array['flexibility', 'interaction', 'motivation', 'access', 'supervision']::text[]),
