select 'b0000000-0000-4000-8000-000000000301', '周末的计划 · Weekend plans', 'Making plans with a friend: times, places and what to do if it rains.', 'zh', 'elementary', 3, id, 'LinguaFlow', 2, true, true
from public.topics where slug = 'daily-conversation'
on conflict (id) do nothing;
select 'b0000000-0000-4000-8000-000000000301'::uuid, v.position, v.text, v.translation_vi from (values
  (1, '这个周末你打算做什么？', 'Cuối tuần này bạn định làm gì?'),
  (2, '我想先去超市买点儿东西，然后回家做饭。', 'Mình muốn đi siêu thị mua ít đồ trước, sau đó về nhà nấu cơm.'),
  (3, '天气好的话，我们可以一起去公园走走。', 'Nếu thời tiết đẹp, chúng ta có thể cùng đi dạo công viên.'),
  (4, '听说新开的那家咖啡馆很不错。', 'Nghe nói quán cà phê mới mở kia khá được.'),
  (5, '你周六上午有空吗？', 'Sáng thứ Bảy bạn có rảnh không?'),
  (6, '不好意思，我上午要去图书馆还书。', 'Xin lỗi, buổi sáng mình phải đến thư viện trả sách.'),
  (7, '那我们下午三点在学校门口见吧。', 'Vậy chúng ta gặp nhau ở cổng trường lúc ba giờ chiều nhé.'),
  (8, '别忘了带上你的照相机。', 'Đừng quên mang theo máy ảnh của bạn.'),
  (9, '如果下雨，我们就在家看电影。', 'Nếu trời mưa, chúng ta sẽ ở nhà xem phim.'),
  (10, '好的，到时候我给你打电话。', 'Được, đến lúc đó mình sẽ gọi điện cho bạn.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000301');

select 'b0000000-0000-4000-8000-000000000302', '在火车站 · At the train station', 'Buying tickets, asking about times and helping with luggage.', 'zh', 'elementary', 3, id, 'LinguaFlow', 2, true, true
from public.topics where slug = 'travel'
on conflict (id) do nothing;
select 'b0000000-0000-4000-8000-000000000302'::uuid, v.position, v.text, v.translation_vi from (values
  (1, '请问，去北京的火车几点出发？', 'Xin hỏi, tàu đi Bắc Kinh mấy giờ khởi hành?'),
  (2, '下一班车是十点二十分的。', 'Chuyến tiếp theo là chuyến mười giờ hai mươi.'),
  (3, '我要买两张票，一张大人的，一张孩子的。', 'Tôi muốn mua hai vé, một vé người lớn, một vé trẻ em.'),
  (4, '坐火车去比坐飞机便宜多了。', 'Đi tàu hỏa rẻ hơn nhiều so với đi máy bay.'),
  (5, '从这儿到北京大概需要五个小时。', 'Từ đây đến Bắc Kinh mất khoảng năm tiếng.'),
  (6, '你的行李箱太重了，我帮你拿吧。', 'Vali của bạn nặng quá, để mình xách giúp nhé.'),
  (7, '车上可以买到吃的和喝的。', 'Trên tàu có thể mua được đồ ăn và đồ uống.'),
  (8, '我们的座位在八号车厢。', 'Chỗ ngồi của chúng ta ở toa số tám.'),
  (9, '别着急，离开车还有半个小时。', 'Đừng vội, còn nửa tiếng nữa tàu mới chạy.'),
  (10, '到了以后记得给妈妈发个短信。', 'Đến nơi rồi nhớ nhắn tin cho mẹ nhé.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000302');

select 'b0000000-0000-4000-8000-000000000401', '第一次面试 · My first job interview', 'Preparing for an interview, answering questions and waiting for the result.', 'zh', 'intermediate', 4, id, 'LinguaFlow', 3, true, true
from public.topics where slug = 'business-career'
on conflict (id) do nothing;
select 'b0000000-0000-4000-8000-000000000401'::uuid, v.position, v.text, v.translation_vi from (values
  (1, '明天下午我有一个很重要的面试。', 'Chiều mai tôi có một buổi phỏng vấn rất quan trọng.'),
  (2, '为了这次机会，我准备了整整一个星期。', 'Vì cơ hội lần này, tôi đã chuẩn bị suốt cả một tuần.'),
  (3, '面试的时候一定要准时，最好提前十分钟到。', 'Khi phỏng vấn nhất định phải đúng giờ, tốt nhất nên đến sớm mười phút.'),
  (4, '经理问我为什么想来他们公司工作。', 'Giám đốc hỏi tôi vì sao muốn đến công ty họ làm việc.'),
  (5, '我说我对这个行业一直很感兴趣。', 'Tôi nói rằng tôi luôn rất hứng thú với ngành này.'),
  (6, '虽然我的经验不多，但是我学东西很快。', 'Tuy kinh nghiệm của tôi không nhiều, nhưng tôi học rất nhanh.'),
  (7, '他们希望新同事能适应加班。', 'Họ hy vọng đồng nghiệp mới có thể thích nghi với việc tăng ca.'),
  (8, '面试结束后，我礼貌地向他们表示感谢。', 'Sau khi phỏng vấn kết thúc, tôi lịch sự cảm ơn họ.'),
  (9, '他们说一周之内会通知我结果。', 'Họ nói trong vòng một tuần sẽ thông báo kết quả cho tôi.'),
  (10, '不管结果怎么样，这都是一次很好的经验。', 'Dù kết quả thế nào, đây đều là một trải nghiệm rất tốt.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000401');

select 'b0000000-0000-4000-8000-000000000402', '租房子 · Renting a flat', 'Looking at a flat, talking about rent and signing the contract.', 'zh', 'intermediate', 4, id, 'LinguaFlow', 3, true, true
from public.topics where slug = 'daily-conversation'
on conflict (id) do nothing;
select 'b0000000-0000-4000-8000-000000000402'::uuid, v.position, v.text, v.translation_vi from (values
  (1, '我最近在找房子，想离公司近一点儿。', 'Dạo này tôi đang tìm nhà, muốn gần công ty hơn một chút.'),
  (2, '这套房子虽然不大，但是阳光很好。', 'Căn nhà này tuy không lớn nhưng rất nhiều nắng.'),
  (3, '房租每个月三千块，水电费另算。', 'Tiền thuê mỗi tháng ba nghìn tệ, tiền điện nước tính riêng.'),
  (4, '附近有地铁站，上下班很方便。', 'Gần đó có ga tàu điện ngầm, đi làm rất tiện.'),
  (5, '房东说至少要租一年。', 'Chủ nhà nói phải thuê ít nhất một năm.'),
  (6, '我能不能先看看厨房和洗手间？', 'Tôi có thể xem bếp và nhà vệ sinh trước không?'),
  (7, '楼下就是超市，买东西不用走很远。', 'Ngay dưới tầng là siêu thị, mua đồ không cần đi xa.'),
  (8, '签合同以前，最好把每一条都看清楚。', 'Trước khi ký hợp đồng, tốt nhất nên đọc kỹ từng điều khoản.'),
  (9, '我打算这个周末就搬过去。', 'Tôi định cuối tuần này chuyển qua luôn.'),
  (10, '搬家那天，几个朋友来帮了我很大的忙。', 'Hôm chuyển nhà, mấy người bạn đến giúp tôi rất nhiều.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000402');

select 'b0000000-0000-4000-8000-000000000501', '网上学习的利与弊 · Pros and cons of online learning', 'A short opinion piece on flexibility, self-discipline and screen time.', 'zh', 'upper_intermediate', 5, id, 'LinguaFlow', 4, true, true
from public.topics where slug = 'education'
on conflict (id) do nothing;
select 'b0000000-0000-4000-8000-000000000501'::uuid, v.position, v.text, v.translation_vi from (values
  (1, '随着网络的发展，越来越多的人选择在网上学习。', 'Cùng với sự phát triển của Internet, ngày càng nhiều người chọn học trực tuyến.'),
  (2, '网上课程最大的优势是时间安排比较灵活。', 'Ưu thế lớn nhất của khóa học trực tuyến là sắp xếp thời gian khá linh hoạt.'),
  (3, '无论你在哪儿，只要有电脑就能上课。', 'Dù bạn ở đâu, chỉ cần có máy tính là có thể học.'),
  (4, '然而，缺少老师的监督，有些人很难坚持下去。', 'Tuy nhiên, thiếu sự giám sát của giáo viên, một số người rất khó kiên trì.'),
  (5, '长时间盯着屏幕，对眼睛也有一定的影响。', 'Nhìn màn hình trong thời gian dài cũng ảnh hưởng nhất định đến mắt.'),
  (6, '专家建议学习者给自己制定一个明确的计划。', 'Chuyên gia khuyên người học nên lập cho mình một kế hoạch rõ ràng.'),
  (7, '和同学互相交流，也能提高学习的效率。', 'Trao đổi với bạn học cũng có thể nâng cao hiệu quả học tập.'),
  (8, '总的来说，网上学习适合自觉性比较强的人。', 'Nhìn chung, học trực tuyến phù hợp với người có tính tự giác cao.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000501');

select 'b0000000-0000-4000-8000-000000000502', '一部改变我的电影 · A film that changed me', 'A personal story about a film, a quote and a new daily habit.', 'zh', 'upper_intermediate', 5, id, 'LinguaFlow', 4, true, true
from public.topics where slug = 'entertainment'
