select 'b0000000-0000-4000-8000-000000000502'::uuid, v.position, v.text, v.translation_vi from (values
  (1, '上大学的时候，我偶然看了一部关于梦想的电影。', 'Hồi học đại học, tôi tình cờ xem một bộ phim về ước mơ.'),
  (2, '主人公出生在一个普通的农村家庭。', 'Nhân vật chính sinh ra trong một gia đình nông thôn bình thường.'),
  (3, '尽管遇到了很多困难，他从来没有放弃过。', 'Mặc dù gặp rất nhiều khó khăn, anh ấy chưa từng bỏ cuộc.'),
  (4, '电影里有一句台词让我印象特别深刻。', 'Trong phim có một câu thoại khiến tôi ấn tượng đặc biệt sâu sắc.'),
  (5, '他说：“机会永远属于有准备的人。”', 'Anh ấy nói: "Cơ hội luôn thuộc về người có sự chuẩn bị."'),
  (6, '看完以后，我开始认真思考自己的未来。', 'Xem xong, tôi bắt đầu nghiêm túc suy nghĩ về tương lai của mình.'),
  (7, '从那以后，我每天早上坚持学一个小时外语。', 'Từ đó trở đi, mỗi sáng tôi kiên trì học ngoại ngữ một tiếng.'),
  (8, '现在回想起来，那部电影确实改变了我的生活态度。', 'Bây giờ nghĩ lại, bộ phim đó thực sự đã thay đổi thái độ sống của tôi.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000502');

select 'b0000000-0000-4000-8000-000000000601', '城市化与乡愁 · Urbanisation and homesickness', 'A reflective talk about moving to big cities and what “home” means.', 'zh', 'advanced', 6, id, 'LinguaFlow', 5, true, true
from public.topics where slug = 'podcast-interviews'
on conflict (id) do nothing;
select 'b0000000-0000-4000-8000-000000000601'::uuid, v.position, v.text, v.translation_vi from (values
  (1, '近几十年来，中国的城市化进程速度惊人。', 'Mấy chục năm gần đây, tốc độ đô thị hóa của Trung Quốc thật đáng kinh ngạc.'),
  (2, '大批年轻人离开家乡，涌入大城市寻找机遇。', 'Rất nhiều người trẻ rời quê, đổ về các thành phố lớn tìm kiếm cơ hội.'),
  (3, '他们在享受便利生活的同时，也承受着巨大的生存压力。', 'Họ vừa tận hưởng cuộc sống tiện nghi, vừa phải chịu áp lực mưu sinh rất lớn.'),
  (4, '每逢春节，火车站里挤满了归心似箭的旅客。', 'Mỗi dịp Tết, nhà ga chật kín những hành khách nóng lòng về quê.'),
  (5, '对许多人而言，“乡愁”已不仅仅是对某个地方的怀念。', 'Với nhiều người, "nỗi nhớ quê" không chỉ đơn thuần là hoài niệm về một nơi chốn.'),
  (6, '它更是一种对传统生活方式和人际关系的眷恋。', 'Đó còn là sự lưu luyến với lối sống truyền thống và các mối quan hệ giữa người với người.'),
  (7, '如何在发展经济的同时保留文化记忆，是一个值得深思的问题。', 'Làm sao vừa phát triển kinh tế vừa lưu giữ ký ức văn hóa là một vấn đề đáng suy ngẫm.'),
  (8, '或许，真正的家乡始终存在于我们的心中。', 'Có lẽ, quê hương thực sự luôn tồn tại trong trái tim chúng ta.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000601');

select 'b0000000-0000-4000-8000-000000000602', '人工智能时代的职业选择 · Careers in the age of AI', 'Which jobs change, which skills matter, and how to keep learning.', 'zh', 'advanced', 6, id, 'LinguaFlow', 5, true, true
from public.topics where slug = 'business-career'
on conflict (id) do nothing;
select 'b0000000-0000-4000-8000-000000000602'::uuid, v.position, v.text, v.translation_vi from (values
  (1, '人工智能的迅速普及，正在深刻地改变着就业市场。', 'Sự phổ biến nhanh chóng của trí tuệ nhân tạo đang thay đổi sâu sắc thị trường việc làm.'),
  (2, '一些重复性强的岗位面临着被取代的风险。', 'Một số vị trí mang tính lặp lại cao đang đối mặt nguy cơ bị thay thế.'),
  (3, '与此同时，也涌现出了许多前所未有的新职业。', 'Đồng thời, cũng xuất hiện nhiều nghề mới chưa từng có.'),
  (4, '专家指出，创造力和沟通能力将变得愈发重要。', 'Chuyên gia chỉ ra rằng khả năng sáng tạo và giao tiếp sẽ ngày càng quan trọng.'),
  (5, '因此，终身学习已经成为每个人不可回避的课题。', 'Vì vậy, học tập suốt đời đã trở thành vấn đề mà ai cũng không thể né tránh.'),
  (6, '与其担心被机器淘汰，不如主动学会与之合作。', 'Thay vì lo bị máy móc đào thải, chi bằng chủ động học cách hợp tác với nó.'),
  (7, '在选择专业时，年轻人应当兼顾兴趣与社会需求。', 'Khi chọn ngành học, người trẻ nên cân nhắc cả sở thích lẫn nhu cầu xã hội.'),
  (8, '归根结底，技术只是工具，人的价值在于判断与创造。', 'Suy cho cùng, công nghệ chỉ là công cụ, giá trị của con người nằm ở khả năng phán đoán và sáng tạo.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000602');

select 'b0000000-0000-4000-8000-000000000e01', 'Morning Routine', 'Everyday habits from waking up to getting to work.', 'en', 'elementary', null, id, 'LinguaFlow', 2, true, true
from public.topics where slug = 'daily-conversation'
on conflict (id) do nothing;
select 'b0000000-0000-4000-8000-000000000e01'::uuid, v.position, v.text, v.translation_vi from (values
  (1, 'I usually wake up at half past six.', 'Tôi thường thức dậy lúc sáu giờ rưỡi.'),
  (2, 'The first thing I do is drink a glass of water.', 'Việc đầu tiên tôi làm là uống một cốc nước.'),
  (3, 'Then I take a quick shower and get dressed.', 'Sau đó tôi tắm nhanh và mặc quần áo.'),
  (4, 'I don''t have much time for breakfast on weekdays.', 'Vào các ngày trong tuần tôi không có nhiều thời gian ăn sáng.'),
  (5, 'Most mornings I just have toast and a cup of coffee.', 'Hầu hết các buổi sáng tôi chỉ ăn bánh mì nướng và một tách cà phê.'),
  (6, 'I leave the house at about a quarter past seven.', 'Tôi ra khỏi nhà vào khoảng bảy giờ mười lăm.'),
  (7, 'It takes me twenty minutes to get to work by bus.', 'Tôi mất hai mươi phút để đi làm bằng xe buýt.'),
  (8, 'On the bus, I listen to podcasts to practise my listening.', 'Trên xe buýt, tôi nghe podcast để luyện nghe.'),
  (9, 'On Sundays, I sleep in and make a big breakfast.', 'Vào Chủ nhật, tôi ngủ nướng và làm một bữa sáng thịnh soạn.'),
  (10, 'A good morning routine makes the whole day better.', 'Một thói quen buổi sáng tốt giúp cả ngày tốt hơn.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000e01');

select 'b0000000-0000-4000-8000-000000000e02', 'Lost Luggage', 'A suitcase goes missing after a flight — past tenses and reported speech.', 'en', 'intermediate', null, id, 'LinguaFlow', 3, true, true
from public.topics where slug = 'travel'
on conflict (id) do nothing;
select 'b0000000-0000-4000-8000-000000000e02'::uuid, v.position, v.text, v.translation_vi from (values
  (1, 'When we landed, I realised my suitcase hadn''t arrived.', 'Khi hạ cánh, tôi nhận ra vali của mình chưa đến.'),
  (2, 'I went to the baggage desk and explained the problem.', 'Tôi đến quầy hành lý và giải thích vấn đề.'),
  (3, 'The woman asked me to fill in a form with my contact details.', 'Người phụ nữ yêu cầu tôi điền vào mẫu đơn với thông tin liên lạc.'),
  (4, 'She said it had probably been put on the wrong flight.', 'Cô ấy nói có lẽ nó đã bị đưa lên nhầm chuyến bay.'),
  (5, 'They promised to deliver it to my hotel within two days.', 'Họ hứa sẽ giao nó đến khách sạn của tôi trong vòng hai ngày.'),
  (6, 'Luckily, I had packed a change of clothes in my hand luggage.', 'May mắn là tôi đã để một bộ quần áo thay trong hành lý xách tay.'),
  (7, 'The next evening, the receptionist called to say it had arrived.', 'Tối hôm sau, lễ tân gọi điện báo rằng nó đã đến.'),
  (8, 'Since then, I''ve always kept the essentials in my backpack.', 'Từ đó, tôi luôn để những thứ thiết yếu trong ba lô.')
) as v(position, text, translation_vi)
where not exists (select 1 from public.lesson_sentences where lesson_id = 'b0000000-0000-4000-8000-000000000e02');

